svg.script:
(function(){
  var thisScript=document.currentScript;

  function ready(fn){
    if(document.readyState!=="loading"){fn();}
    else{document.addEventListener("DOMContentLoaded",fn);}
  }

  ready(function(){
    var svg=(thisScript&&thisScript.closest)?thisScript.closest("svg"):null;
    if(!svg){svg=document.querySelector("svg");}
    if(!svg){return;}
    var regions=Array.prototype.slice.call(svg.querySelectorAll(".region"));

    function sameProvinceGroup(el){
      var prov=el.getAttribute("data-province");
      return regions.filter(function(r){return r.getAttribute("data-province")===prov;});
    }

    regions.forEach(function(el){
      el.addEventListener("mouseenter",function(){
        sameProvinceGroup(el).forEach(function(r){
          if(r!==el){r.classList.add("hover-group");}
        });
      });
      el.addEventListener("mouseleave",function(){
        sameProvinceGroup(el).forEach(function(r){
          r.classList.remove("hover-group");
        });
      });
      el.addEventListener("click",function(){
        var group=sameProvinceGroup(el);
        var alreadySelected=group.every(function(r){return r.classList.contains("selected");});
        regions.forEach(function(r){r.classList.remove("selected");});
        if(!alreadySelected){
          group.forEach(function(r){r.classList.add("selected");});
        }
      });
    });
  });
})();
